const now = new Date();
return [{
  json: {
    location_id: 'ZzRtp9n8n76ARy99VzJc',
    supabase_url: 'https://mhfncmxlpwzyuupxjlxo.supabase.co',
    ghl_api_version: 'v3',

    legacy_pipeline_id: 'L9nSVkwjFsHN5WFDs3Aa',
    legacy_pipeline_name: 'Antiguo Leads Milhano',

    setter_pipeline_id: 'GYqHbZyWUxxc3K03efVT',
    setter_pipeline_name: 'Leads Milhano (Setter pipeline)',

    closer_pipeline_id: 'z1FEJfbtOHusjdwe40Ko',
    closer_pipeline_name: 'Leads Milhano (Closer Pipeline)',

    refresh_key: 'PASTE_SAME_VALUE_AS_MILHANO_N8N_REFRESH_KEY',
    sync_started_at: now.toISOString(),
    workflow_name: 'MILHANO | 01 | Opportunities Full Reconciliation V4.1 | Exact GHL Pipelines'
  }
}];

const response = $input.first().json;
const config = $('Config | MILHANO').first().json;

function extractPipelines(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.pipelines)) return payload.pipelines;
  if (Array.isArray(payload?.data?.pipelines)) return payload.data.pipelines;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.body?.pipelines)) return payload.body.pipelines;
  return [];
}

const pipelines = extractPipelines(response);
if (!pipelines.length) throw new Error('GHL no devolvió pipelines.');

function norm(v) {
  return String(v ?? '')
    .trim()
    .toLocaleLowerCase('es')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}
function slug(v) {
  return norm(v).replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}
function classify(name) {
  const n = norm(name);
  if (/lost|disqual|no fit|sin continuidad/.test(n)) return 'salida';
  if (/nurtur|no answer|seguimiento|callback|cancel/.test(n)) return 'seguimiento';
  if (/closed|inscrito/.test(n)) return 'resultado';
  if (/qualified|fit|tour|pasadia|meaningful|atendido|asistida|agendada/.test(n)) return 'hito';
  return 'entrada';
}
function positive(name) {
  const n = norm(name);
  return /qualified|fit|meaningful|tour booked|tour attended|pasadia booked|pasadia attended|school tour agendado|school tour atendido|pasadia agendada|pasadia asistida|closed|inscrito/.test(n);
}
function findPipeline(id) {
  return pipelines.find(p => String(p?.id ?? p?._id ?? '') === String(id));
}

const legacy = findPipeline(config.legacy_pipeline_id);
const setter = findPipeline(config.setter_pipeline_id);
const closer = findPipeline(config.closer_pipeline_id);

if (!legacy || !setter || !closer) {
  const available = pipelines
    .map(p => `${p?.name ?? '(sin nombre)'} [${p?.id ?? p?._id ?? '(sin id)'}]`)
    .join(' | ');
  const missing = [
    !legacy ? `Antiguo Leads Milhano [${config.legacy_pipeline_id}]` : null,
    !setter ? `Leads Milhano (Setter pipeline) [${config.setter_pipeline_id}]` : null,
    !closer ? `Leads Milhano (Closer Pipeline) [${config.closer_pipeline_id}]` : null,
  ].filter(Boolean).join(', ');
  throw new Error(`No se resolvieron: ${missing}. GHL devolvió: ${available}`);
}

function build(role, pipeline) {
  const stage_map = {};
  const stages = Array.isArray(pipeline?.stages)
    ? pipeline.stages
    : Array.isArray(pipeline?.pipelineStages)
      ? pipeline.pipelineStages
      : [];

  const stage_catalog_rows = stages.map((stage, index) => {
    const stageName = String(stage?.name ?? '').trim();
    const stageId = String(stage?.id ?? stage?._id ?? '').trim();
    if (stageId) stage_map[stageId] = stageName;

    return {
      pipeline_id: String(pipeline.id ?? pipeline._id),
      pipeline_name: String(pipeline.name ?? ''),
      pipeline_role: role,
      stage_id: stageId || null,
      stage_name: stageName,
      canonical_key: `${role}_${slug(stageName)}`,
      display_order: Number(stage.position ?? stage.order ?? ((index + 1) * 10)),
      stage_group: classify(stageName),
      is_positive_milestone: positive(stageName),
      updated_at: new Date().toISOString(),
    };
  });

  return { pipeline, stage_map, stage_catalog_rows };
}

const resolved = {
  legacy: build('legacy', legacy),
  setter: build('setter', setter),
  closer: build('closer', closer),
};

const startItems = $('Supabase | Start Sync Run').all();
let syncRunId = null;
for (const item of startItems) {
  const v = item.json;
  if (v?.id) syncRunId = v.id;
  if (Array.isArray(v) && v[0]?.id) syncRunId = v[0].id;
  if (v?.data?.id) syncRunId = v.data.id;
  if (Array.isArray(v?.data) && v.data[0]?.id) syncRunId = v.data[0].id;
}
if (!syncRunId) throw new Error('No se recuperó milhano_sync_runs.id.');

return [{
  json: {
    sync_run_id: syncRunId,

    legacy_pipeline: resolved.legacy.pipeline,
    legacy_stage_map: resolved.legacy.stage_map,

    setter_pipeline: resolved.setter.pipeline,
    setter_stage_map: resolved.setter.stage_map,

    closer_pipeline: resolved.closer.pipeline,
    closer_stage_map: resolved.closer.stage_map,

    stage_catalog_rows: [
      ...resolved.legacy.stage_catalog_rows,
      ...resolved.setter.stage_catalog_rows,
      ...resolved.closer.stage_catalog_rows,
    ],

    resolved_pipeline_ids: {
      legacy: String(legacy.id ?? legacy._id),
      setter: String(setter.id ?? setter._id),
      closer: String(closer.id ?? closer._id),
    },

    resolved_pipeline_names: {
      legacy: String(legacy.name ?? ''),
      setter: String(setter.name ?? ''),
      closer: String(closer.name ?? ''),
    },
  },
}];

const selection=$('Resolve | Admissions Pipelines').first().json;
const config=$('Config | MILHANO').first().json;
const now=new Date().toISOString();

const advisorNames={
  '77kxc0w2hMphBCnyl9Fe':'Cinthia Esquivel',
  'LTJEPAdClnxPxUd2mRXp':'Pathi Carrillo'
};

function toIso(value){
  if(value===null||value===undefined||value==='') return null;
  let normalized=value;
  if(typeof value==='number'&&value<100000000000) normalized=value*1000;
  const d=new Date(normalized);
  return Number.isNaN(d.getTime())?null:d.toISOString();
}
function clean(value){
  if(value===null||value===undefined) return null;
  const t=String(value).trim();
  return t.length?t:null;
}
function extract(payload){
  if(!payload) return [];
  if(Array.isArray(payload)) return payload.flatMap(extract);
  if(Array.isArray(payload.opportunities)) return payload.opportunities;
  if(Array.isArray(payload.data?.opportunities)) return payload.data.opportunities;
  if(Array.isArray(payload.body?.opportunities)) return payload.body.opportunities;
  return [];
}
function normalizePages(nodeName,pipeline,stageMap,role){
  return $(nodeName).all()
    .flatMap(item=>extract(item.json))
    .map(opp=>{
      const id=clean(opp.id ?? opp._id ?? opp.opportunityId);
      if(!id) return null;
      const contact=opp.contact&&typeof opp.contact==='object'?opp.contact:{};
      const contactId=clean(opp.contactId ?? opp.contact_id ?? contact.id ?? contact._id);
      const assignedUserId=clean(opp.assignedTo ?? opp.assignedToId ?? opp.assignedUserId ?? opp.userId);
      const stageId=clean(opp.pipelineStageId ?? opp.pipeline_stage_id ?? opp.stageId);
      const createdAt=toIso(opp.dateAdded ?? opp.createdAt ?? opp.created_at);
      const updatedAt=toIso(opp.dateUpdated ?? opp.updatedAt ?? opp.updated_at ?? opp.lastStatusChangeAt ?? createdAt);
      const pipelineUpdatedAt=toIso(opp.lastStageChangeAt ?? opp.pipelineStageChangedAt ?? opp.stageChangedAt ?? updatedAt);
      const liveLostReason=clean(opp.lostReason?.name ?? opp.lostReason?.label ?? (typeof opp.lostReason==='string'?opp.lostReason:null));
      return {
        ghl_opportunity_id:id,
        ghl_contact_id:contactId,
        pipeline_id:String(pipeline.id),
        pipeline_name:String(pipeline.name),
        pipeline_stage_id:stageId,
        current_stage:clean(stageMap[stageId]) ?? clean(opp.pipelineStageName) ?? clean(opp.stageName),
        status:clean(opp.status),
        opportunity_name:clean(opp.name ?? opp.opportunityName),
        contact_name:clean(contact.name ?? opp.contactName ?? [contact.firstName,contact.lastName].filter(Boolean).join(' ')),
        phone:clean(contact.phone ?? opp.phone ?? opp.contactPhone),
        email:clean(contact.email ?? opp.email ?? opp.contactEmail),
        source:clean(opp.source ?? contact.source),
        assigned_user:advisorNames[assignedUserId] ?? clean(opp.assignedToName) ?? assignedUserId,
        created_at:createdAt,
        updated_at:updatedAt,
        location_id:config.location_id,
        assigned_user_id:assignedUserId,
        pipeline_updated_at:pipelineUpdatedAt,
        ghl_lost_reason_id:clean(opp.lostReasonId),
        live_lost_reason:liveLostReason,
        ghl_custom_fields:Array.isArray(opp.customFields)?opp.customFields:[],
        ghl_calendar_events:Array.isArray(opp.calendarEvents)?opp.calendarEvents:[],
        last_truth_synced_at:now,
        last_synced_at:now,
        sync_source:'ghl_truth_reconciliation_v4',
        truth_pipeline_role:role,
      };
    })
    .filter(Boolean);
}

const legacyRows=normalizePages('GHL | Search Legacy Opportunities',selection.legacy_pipeline,selection.legacy_stage_map??{},'legacy');
const setterRows=normalizePages('GHL | Search Setter Opportunities',selection.setter_pipeline,selection.setter_stage_map??{},'setter');
const closerRows=normalizePages('GHL | Search Closer Opportunities',selection.closer_pipeline,selection.closer_stage_map??{},'closer');

const deduped=new Map();
for(const row of [...legacyRows,...setterRows,...closerRows]){
  const existing=deduped.get(row.ghl_opportunity_id);
  if(!existing || String(row.updated_at??'')>=String(existing.updated_at??'')){
    deduped.set(row.ghl_opportunity_id,row);
  }
}
const liveRows=[...deduped.values()];
if(!liveRows.length) throw new Error('Los 3 pipelines no devolvieron opportunities.');

return [{json:{
  sync_run_id:selection.sync_run_id,
  location_id:config.location_id,
  pipeline_ids:[String(selection.legacy_pipeline.id),String(selection.setter_pipeline.id),String(selection.closer_pipeline.id)],
  pipeline_names:[String(selection.legacy_pipeline.name),String(selection.setter_pipeline.name),String(selection.closer_pipeline.name)],
  legacy_records:legacyRows.length,
  setter_records:setterRows.length,
  closer_records:closerRows.length,
  records_read:liveRows.length,
  live_rows:liveRows,
  synced_at:now
}}];

const snapshot = $('Normalize | 3 Pipeline Snapshot').first().json;

function rowsFromNode(nodeName, primaryKey) {
  const result = [];

  for (const item of $(nodeName).all()) {
    const value = item.json;

    if (Array.isArray(value)) {
      result.push(...value);
      continue;
    }

    if (Array.isArray(value?.data)) {
      result.push(...value.data);
      continue;
    }

    if (Array.isArray(value?.body)) {
      result.push(...value.body);
      continue;
    }

    if (value && value[primaryKey]) {
      result.push(value);
    }
  }

  return result;
}

function preferLive(liveValue, existingValue) {
  return liveValue === null || liveValue === undefined || liveValue === ''
    ? (existingValue ?? null)
    : liveValue;
}

const existingOpportunities = rowsFromNode(
  'Supabase | Get Existing Opportunities',
  'ghl_opportunity_id'
);

const existingContacts = rowsFromNode(
  'Supabase | Get Existing Contacts',
  'ghl_contact_id'
);

const existingOpportunityMap = new Map(
  existingOpportunities.map((row) => [row.ghl_opportunity_id, row])
);

const existingContactMap = new Map(
  existingContacts.map((row) => [row.ghl_contact_id, row])
);

const opportunityRows = [];
const contactCandidates = new Map();
const opportunitiesPerContact = new Map();

for (const live of snapshot.live_rows) {
  const existing = existingOpportunityMap.get(live.ghl_opportunity_id);
  const isNew = !existing;

  const { live_lost_reason, truth_pipeline_role, ...liveDb } = live;
  const merged = {
    ...(existing ?? {}),
    ...liveDb,

    // Estos datos pueden venir vacíos en algunas respuestas de GHL.
    contact_name: preferLive(live.contact_name, existing?.contact_name),
    phone: preferLive(live.phone, existing?.phone),
    email: preferLive(live.email, existing?.email),
    source: preferLive(live.source, existing?.source),

    // Nunca reemplazamos campos históricos reconstruidos.
    legacy_lead_id: existing?.legacy_lead_id ?? null,
    original_lead_date: existing?.original_lead_date ?? null,
    student_name: existing?.student_name ?? null,
    school_cycle: existing?.school_cycle ?? null,
    level: existing?.level ?? null,
    grade_interest: existing?.grade_interest ?? null,
    priority: existing?.priority ?? null,
    historical_advisor: existing?.historical_advisor ?? null,
    admission_route: existing?.admission_route ?? null,
    direct_admission_reason: existing?.direct_admission_reason ?? null,
    no_fit_reason: existing?.no_fit_reason ?? null,
    lost_reason: live.live_lost_reason ?? existing?.lost_reason ?? null,
    historical_call_count: existing?.historical_call_count ?? null,
    historical_comments: existing?.historical_comments ?? null,

    // Campo NOT NULL: se conserva para migrados y sólo se crea para nuevos.
    history_scope:
      existing?.history_scope ??
      (isNew ? 'live_from_ghl' : 'live_from_ghl'),

    // Conservamos la procedencia de la semilla; los campos sync_* señalan lo live.
    record_source:
      existing?.record_source ??
      'ghl_api_full_reconciliation',

    synced_at: snapshot.synced_at,
    last_synced_at: snapshot.synced_at,
    sync_source: 'ghl_full_reconciliation'
  };

  opportunityRows.push(merged);

  if (merged.ghl_contact_id) {
    opportunitiesPerContact.set(
      merged.ghl_contact_id,
      (opportunitiesPerContact.get(merged.ghl_contact_id) ?? 0) + 1
    );

    const currentCandidate = contactCandidates.get(merged.ghl_contact_id) ?? {};
    contactCandidates.set(merged.ghl_contact_id, {
      ghl_contact_id: merged.ghl_contact_id,
      contact_name: preferLive(merged.contact_name, currentCandidate.contact_name),
      phone: preferLive(merged.phone, currentCandidate.phone),
      email: preferLive(merged.email, currentCandidate.email),
      latest_opportunity_updated_at:
        !currentCandidate.latest_opportunity_updated_at ||
        String(merged.updated_at ?? '') > String(currentCandidate.latest_opportunity_updated_at ?? '')
          ? merged.updated_at
          : currentCandidate.latest_opportunity_updated_at
    });
  }
}

const contactRows = [];

for (const [contactId, candidate] of contactCandidates.entries()) {
  const existing = existingContactMap.get(contactId);
  const isNew = !existing;

  contactRows.push({
    ...(existing ?? {}),
    ghl_contact_id: contactId,
    contact_name: preferLive(candidate.contact_name, existing?.contact_name),
    phone: preferLive(candidate.phone, existing?.phone),
    email: preferLive(candidate.email, existing?.email),
    opportunity_count:
      existing?.opportunity_count ??
      opportunitiesPerContact.get(contactId) ??
      1,
    first_seen_in_export:
      existing?.first_seen_in_export ??
      (isNew ? snapshot.synced_at : null),
    last_seen_updated_at:
      preferLive(
        candidate.latest_opportunity_updated_at,
        existing?.last_seen_updated_at
      ),
    record_source:
      existing?.record_source ??
      'ghl_api_full_reconciliation',
    synced_at: snapshot.synced_at
  });
}

if (opportunityRows.length !== snapshot.records_read) {
  throw new Error(
    `La conciliación preparó ${opportunityRows.length} filas, pero GHL reportó ${snapshot.records_read}.`
  );
}

return [{
  json: {
    sync_run_id: snapshot.sync_run_id,
    location_id: snapshot.location_id,
    pipeline_ids: snapshot.pipeline_ids,
    pipeline_names: snapshot.pipeline_names,
    legacy_records: snapshot.legacy_records,
    setter_records: snapshot.setter_records,
    closer_records: snapshot.closer_records,
    records_read: snapshot.records_read,
    existing_opportunities: existingOpportunities.length,
    new_opportunities:
      opportunityRows.filter(
        (row) => !existingOpportunityMap.has(row.ghl_opportunity_id)
      ).length,
    existing_contacts: existingContacts.length,
    contacts_to_upsert: contactRows.length,
    opportunity_rows: opportunityRows,
    contact_rows: contactRows,
    finished_at: new Date().toISOString()
  }
}];

const merged = $('Merge | Preserve Historical Data').first().json;
function responseCount(nodeName) {
  let count = 0;
  for (const item of $(nodeName).all()) {
    const value = item.json;
    if (Array.isArray(value)) count += value.length;
    else if (Array.isArray(value?.data)) count += value.data.length;
    else if (value && Object.keys(value).length > 0) count += 1;
  }
  return count;
}
const baseline = null;
return [{ json: {
  sync_run_id: merged.sync_run_id,
  location_id: merged.location_id,
  pipeline_ids: merged.pipeline_ids,
  pipeline_names: merged.pipeline_names,
  legacy_records: merged.legacy_records,
  setter_records: merged.setter_records,
  closer_records: merged.closer_records,
  records_read: merged.records_read,
  existing_opportunities: merged.existing_opportunities,
  new_opportunities: merged.new_opportunities,
  contacts_to_upsert: merged.contacts_to_upsert,
  contacts_returned: responseCount('Supabase | Upsert Contacts'),
  opportunities_returned: responseCount('Supabase | Upsert Opportunities'),
  baseline_response: baseline,
  finished_at: new Date().toISOString()
} }];

const input=$input.first().json;
const expected='PASTE_SAME_VALUE_AS_MILHANO_N8N_REFRESH_KEY';
const supplied=String(input.query?.key ?? input.body?.key ?? '').trim();
if(!expected || expected.startsWith('PASTE_')) throw new Error('Edita Validate | Reconciliation Key y pega la misma key de Vercel.');
if(supplied!==expected) throw new Error('Reconciliation key inválida.');
return [{json:{ok:true,requested_at:new Date().toISOString()}}];
